package ro.leo.visual;
import android.content.*;import java.net.*;import java.io.*;import java.security.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Small authenticated LAN server; only its own exchange folder is addressable. */
final class CompanionServer implements java.io.Closeable {
 static final int LIMIT=16777216;final Context context;final ServerSocket server;final String token;final ThreadPoolExecutor clients=new ThreadPoolExecutor(2,2,0,TimeUnit.SECONDS,new ArrayBlockingQueue<Runnable>(4));volatile boolean running=true;
 CompanionServer(Context c,InetAddress address,int port,String secret)throws IOException{context=c.getApplicationContext();token=secret;server=new ServerSocket();server.setReuseAddress(true);server.bind(new InetSocketAddress(address,port),4);}
 static String token(){byte[] b=new byte[16];new SecureRandom().nextBytes(b);StringBuilder out=new StringBuilder();for(byte value:b)out.append(String.format(Locale.ROOT,"%02x",value&255));return out.toString();}
 static File folder(Context c){File f=new File(c.getFilesDir(),"documents/Companion");f.mkdirs();return f;}
 static boolean name(String value){return value!=null&&value.matches("[A-Za-z0-9][A-Za-z0-9._ -]{0,79}")&&!value.contains("..");}
 static boolean authenticated(String provided,String expected){return provided!=null&&MessageDigest.isEqual(provided.getBytes(java.nio.charset.StandardCharsets.UTF_8),("Bearer "+expected).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 void start(){new Thread(new Runnable(){public void run(){while(running)try{final Socket socket=server.accept();try{clients.execute(new Runnable(){public void run(){serve(socket);}});}catch(RejectedExecutionException e){socket.close();}}catch(IOException e){if(running)running=false;}}},"LeoCompanionAccept").start();}
 static String line(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();int b;while((b=in.read())!=-1){if(b==10)break;if(out.size()>=4096)throw new IOException("Line too long");if(b!=13)out.write(b);}if(b==-1&&out.size()==0)throw new EOFException();return out.toString("US-ASCII");}
 void serve(Socket socket){try(Socket s=socket){s.setSoTimeout(5000);InputStream in=s.getInputStream();OutputStream out=s.getOutputStream();String[] request=line(in).split(" ");if(request.length!=3||!request[2].equals("HTTP/1.1")){reply(out,400,"text/plain","Bad request");return;}Map<String,String> headers=new HashMap<String,String>();int size=0;for(int k=0;k<32;k++){String h=line(in);size+=h.length();if(size>16384)throw new IOException();if(h.isEmpty())break;int split=h.indexOf(':');if(split<1)throw new IOException();String key=h.substring(0,split).trim().toLowerCase(Locale.ROOT);if(headers.containsKey(key))throw new IOException();headers.put(key,h.substring(split+1).trim());if(k==31)throw new IOException();}String host=headers.get("host"),own=server.getInetAddress().getHostAddress()+":"+server.getLocalPort();if(!own.equals(host)){reply(out,403,"text/plain","Host rejected");return;}String origin=headers.get("origin");if(origin!=null&&!origin.equals("http://"+own)){reply(out,403,"text/plain","Origin rejected");return;}String method=request[0],path=request[1];if(method.equals("GET")&&path.equals("/")){try(InputStream html=context.getAssets().open("companion.html")){byte[] body=new byte[32768];int count=0,n;while((n=html.read(body,count,body.length-count))>0){count+=n;if(count==body.length)throw new IOException();}respond(out,200,"text/html; charset=utf-8",Arrays.copyOf(body,count));}return;}if(!authenticated(headers.get("authorization"),token)){reply(out,401,"text/plain","Authentication required");return;}if(method.equals("GET")&&path.equals("/api/status")){JSONObject status=new JSONObject().put("platform","Leo Android 8.1").put("api",android.os.Build.VERSION.SDK_INT).put("health",ShellHealth.status(context)).put("free_bytes",folder(context).getUsableSpace()).put("scope","Companion exchange folder only");reply(out,200,"application/json",status.toString());}else if(method.equals("GET")&&path.equals("/api/files")){JSONArray files=new JSONArray();File[] all=folder(context).listFiles();if(all!=null)for(File f:all)if(files.length()<64&&f.isFile()&&name(f.getName()))files.put(new JSONObject().put("name",f.getName()).put("bytes",f.length()));reply(out,200,"application/json",files.toString());}else if(method.equals("GET")&&path.startsWith("/api/file/")){String filename=URLDecoder.decode(path.substring(10),"UTF-8");if(!name(filename))throw new IOException();File file=new File(folder(context),filename);if(!file.isFile()||file.length()>LIMIT){reply(out,404,"text/plain","Not found");return;}head(out,200,"application/octet-stream",file.length());try(InputStream data=new FileInputStream(file)){byte[] bytes=new byte[16384];int n;while((n=data.read(bytes))!=-1)out.write(bytes,0,n);}}else if(method.equals("POST")&&path.equals("/api/upload")){if(headers.containsKey("transfer-encoding"))throw new IOException();String filename=headers.get("x-leo-name");long length=Long.parseLong(headers.get("content-length"));if(!name(filename)||length<0||length>LIMIT||folder(context).getUsableSpace()<length+2097152){reply(out,413,"text/plain","Invalid name or size; maximum 16 MB");return;}File target=new File(folder(context),filename);if(target.exists()){reply(out,409,"text/plain","File already exists");return;}File stage=new File(folder(context),".upload-"+UUID.randomUUID());try{try(FileOutputStream file=new FileOutputStream(stage)){byte[] bytes=new byte[16384];long remaining=length;while(remaining>0){int n=in.read(bytes,0,(int)Math.min(bytes.length,remaining));if(n<0)throw new EOFException();file.write(bytes,0,n);remaining-=n;}file.getFD().sync();}if(target.exists()||!stage.renameTo(target))throw new IOException();reply(out,201,"application/json","{\"uploaded\":true}");}finally{stage.delete();}}else reply(out,404,"text/plain","Unknown endpoint");out.flush();}catch(Exception ignored){}}
 static void reply(OutputStream out,int status,String type,String body)throws IOException{respond(out,status,type,body.getBytes("UTF-8"));}
 static void respond(OutputStream out,int status,String type,byte[] body)throws IOException{head(out,status,type,body.length);out.write(body);out.flush();}
 static void head(OutputStream out,int status,String type,long bytes)throws IOException{String reason=status==200?"OK":status==201?"Created":"Request rejected";out.write(("HTTP/1.1 "+status+" "+reason+"\r\nContent-Type: "+type+"\r\nContent-Length: "+bytes+"\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nContent-Security-Policy: default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self'; object-src 'none'; frame-ancestors 'none'\r\n\r\n").getBytes("US-ASCII"));}
 public void close(){running=false;try{server.close();}catch(IOException ignored){}clients.shutdownNow();}
}
